// High School course unit (docs/design/COURSES.md, docs/design/COURSE_QUALITY.md): World Geography, Unit 3, Climate and Weather.
// World Geography is not AP. It follows Geography for Life: National Geography Standards (2nd ed., 2012). This unit covers
// NGS 7 (the physical processes that shape the patterns of Earth's surface: here the atmosphere, winds, seasons and storms),
// NGS 8 (the spatial distribution of ecosystems and biomes: here the Koppen climate groups that match them) and NGS 15 (how
// physical systems affect human systems). Our own wording and questions. Students meet weather and climate, the controls on
// climate (latitude, elevation, distance from water, currents, winds, mountains), the global pressure and wind belts, the seasons
// from the 23.5 degree tilt and the Sun's angle at noon, the five Koppen groups, climographs (annual range and total computed from
// fictional monthly data), hurricanes and monsoons, the scientific consensus on climate change in the IPCC's words, and how climate
// shapes where and how people live. Unit 2 met biome bands and the lapse rate; this unit uses them as climate controls. AP
// Environmental Science covers atmospheric chemistry and policy; this unit does not. The unit test recomputes every number and
// re-derives every lettered answer from a rule table written separately.
const tab=(title,rows,cols=['Value'])=>({t:'setups',title,head:'',rows,cols});
/* Lesson figures use 640 x 280 screen positions (y down), converted to the figure renderer's upward y axis.
   Labels stay inside the 44..596 x 56..248 drawing window; shapes reveal in order. */
const scene=(title,draw)=>{const pts={},polys=[],segs=[],circles=[],notes=[];let i=0;const point=(x,y)=>{const k='P'+i++;pts[k]=[x,280-y];return k;};
 const pen={box:(x,y,w,h,col=0,lw)=>{const v=[[x,y],[x+w,y],[x+w,y+h],[x,y+h]].map(([a,b])=>point(a,b)).join('');polys.push(lw?{v,col,w:lw}:{v,col});},
  poly:(list,col=0,lw)=>{const v=list.map(([a,b])=>point(a,b)).join('');polys.push(lw?{v,col,w:lw}:{v,col});},
  line:(x,y,u,v,col=0,arrows=0,dash=false,w=2)=>segs.push({v:point(x,y)+point(u,v),col,arrows,dash,w}),
  circle:(x,y,r,col=0,dash=false)=>circles.push({c:point(x,y),r,col,dash}),
  note:(x,y,text,col=0)=>notes.push({at:[x,280-y],text,col})};
 draw(pen);return {t:'figure',title,view:[44,596,32,224],pts,hide:Object.keys(pts).join(''),dots:'',polys,segs,circles,notes};};
const board=(title,lines)=>({t:'board',title,lines,box:true});
const n=v=>v.toLocaleString('en-US');
const r4=v=>Math.round(v*1e4)/1e4;
const andList=a=>a.slice(0,-1).join(', ')+' and '+a.at(-1);
const MON='JFMAMJJASOND';
const sg=s=>s.endsWith('S')?-parseFloat(s):parseFloat(s);
/* Fictional stations: monthly mean temperature in degrees C and monthly precipitation in mm, January to December. */
const ALDER={t:[-8,-6,0,7,14,19,22,21,15,8,0,-6],p:[30,28,35,50,70,85,90,80,65,50,45,38]};
const BIRCH={t:[25,26,27,28,28,27,26,26,26,26,25,25],p:[250,230,260,280,200,100,60,70,150,230,270,280]};
const CEDAR={t:[12,14,18,23,28,33,36,35,31,25,18,13],p:[5,4,3,2,1,0,0,1,1,2,3,5]};
const DUNE={t:[24,23,21,17,13,10,9,11,14,17,20,23],p:[20,25,35,55,80,100,110,95,70,50,35,25]};
const ELM={t:[-30,-28,-24,-16,-6,2,5,3,-4,-14,-22,-28],p:[15,12,12,14,16,22,30,32,24,22,16,14]};
const FIR={t:[5,5,7,9,12,15,17,17,15,11,8,6],p:[140,110,100,80,70,60,45,55,80,120,150,160]};
const MONSOON=[5,5,5,10,40,300,480,450,270,25,5,5];
const TEAK=[10,10,15,20,60,260,380,350,220,90,25,10];
const DAILY=[24,27,22,29,25,31,26,23,28,25];
/* a climograph: bars are precipitation (right scale), the line is temperature (left scale) */
const climo=(title,T,P,o)=>scene(title,d=>{const {lo,hi,pm}=o,yT=t=>220-(t-lo)*140/(hi-lo),yP=p=>220-p*140/pm,cx=m=>90+37.5*m+18.75;
 d.line(90,80,90,220,0,0,false,2);d.line(540,80,540,220,0,0,false,2);d.line(90,220,540,220,0,0,false,2);
 P.forEach((p,m)=>{if(p>0)d.box(90+37.5*m+6.25,yP(p),25,220-yP(p),1);});
 if(lo<0)d.line(90,yT(0),540,yT(0),4,0,true,1);
 for(let m=0;m<11;m++)d.line(cx(m),yT(T[m]),cx(m+1),yT(T[m+1]),3,0,false,3);
 T.forEach((t,m)=>d.circle(cx(m),yT(t),3,3));
 [...MON].forEach((c,m)=>d.note(cx(m),234,c,0));
 for(const t of [lo,(lo+hi)/2,hi])d.note(68,yT(t),String(t),3);
 for(const p of [0,pm/2,pm])d.note(568,yP(p),String(p),1);
 d.note(100,66,'Temperature (°C)',3);d.note(500,66,'Precipitation (mm)',1);if(o.note)d.note(320,66,o.note,4);});
const weatherFig=()=>scene('Ten days of weather (fictional highs, °C) and one climate average',d=>{
 const X=i=>90+i*45,Y=t=>220-(t-20)*10;
 d.line(70,220,520,220,0,0,false,2);d.line(70,100,70,220,0,0,false,2);
 for(let i=0;i<9;i++)d.line(X(i),Y(DAILY[i]),X(i+1),Y(DAILY[i+1]),1,0,false,2);
 DAILY.forEach((t,i)=>d.circle(X(i),Y(t),4,1));
 d.line(70,Y(26),520,Y(26),3,0,true,3);
 d.note(46,Y(20),'20',0);d.note(46,Y(26),'26',3);d.note(46,Y(32),'32',0);
 d.note(300,236,'Day 1 to day 10',0);d.note(300,76,'Weather: the days jump about',1);d.note(560,Y(26),'Mean 26',3);d.note(560,Y(26)+16,'= climate',3);});
const factorsFig=()=>scene('Six controls on climate',d=>{
 const cells=[['Latitude','sun angle, day length',3],['Elevation','air cools with height',0],['Distance from water','coast: small range',1],['Ocean currents','carry heat along coasts',1],['Prevailing winds','bring air from elsewhere',2],['Mountains','rain side and rain shadow',4]];
 cells.forEach(([a,b,c],k)=>{const x=60+(k%3)*175,y=76+Math.floor(k/3)*84;d.box(x,y,160,64,c);d.note(x+80,y+22,a,c);d.note(x+80,y+44,b,0);});
 d.note(320,238,'Most climates come from several controls working together',4);});
const lapseFig=()=>scene('Cooling with height: 6.5 °C per 1,000 m (fictional base 26 °C)',d=>{
 const Y=h=>230-h*0.04;
 d.poly([[220,230],[400,70],[580,230]],0,2);d.line(60,230,590,230,0,0,false,2);
 for(let k=0;k<=4;k++){const h=1000*k,t=26-6.5*k,sx=220+0.045*h;d.line(165,Y(h),sx,Y(h),k===4?1:3,0,true,1);d.note(112,Y(h)-(k===0?10:0),`${n(h)} m: ${t} °C`,k===4?1:3);}
 d.note(500,120,'Snow line',1);d.note(500,138,'near 0 °C',1);d.note(320,246,'Each 1,000 m climbed: 6.5 °C colder',4);});
const coastFig=()=>scene('Same latitude, different range (fictional stations)',d=>{
 const Y=t=>220-(t+10)*4;
 d.line(90,60,90,220,0,0,false,2);d.line(90,220,330,220,0,0,false,2);d.line(90,Y(0),330,Y(0),4,0,true,1);
 for(const t of [-10,0,10,20,30])d.note(68,Y(t),String(t),0);
 d.box(130,Y(18),70,Y(9)-Y(18),1);d.box(240,Y(27),70,Y(-7)-Y(27),3);
 d.note(165,236,'Port Ash',1);d.note(275,236,'Dry Fork',3);d.note(165,Y(18)-12,'18',1);d.note(165,Y(9)+12,'9',1);d.note(275,Y(27)-12,'27',3);d.note(275,Y(-7)+12,'-7',3);
 d.note(450,84,'Coast: range 9 °C',1);d.note(450,104,'Interior: range 34 °C',3);d.note(450,138,'Warm current:',2);d.note(450,156,'milder coast',2);d.note(450,184,'Cold current:',1);d.note(450,202,'cool, dry coast',1);});
const shadowFig=()=>scene('Mountain, rain and rain shadow (fictional annual rain)',d=>{
 d.poly([[150,220],[320,100],[490,220]],0,2);d.line(50,220,590,220,0,0,false,2);
 d.line(70,196,240,128,1,1,false,3);d.line(380,126,560,196,3,1,true,3);
 d.note(110,160,'Moist air',1);d.note(320,80,'Air rises, cools: cloud and rain',1);d.note(500,150,'Sinks, warms: dry',3);
 d.note(150,238,'Windward: 1,800 mm',1);d.note(490,238,'Leeward: 400 mm',3);});
const beltsFig=()=>scene('Pressure and wind belts, Northern Hemisphere (a simple model)',d=>{
 const Y=la=>225-la*1.75;
 [[0,30,'Trade winds',1,-1],[30,60,'Westerlies',2,1],[60,90,'Polar easterlies',4,-1]].forEach(([a,b,nm,c,dir])=>{d.box(120,Y(b),260,Y(a)-Y(b),c);d.note(250,(Y(a)+Y(b))/2-12,nm,c);
  const y=(Y(a)+Y(b))/2+10;if(dir<0)d.line(340,y,160,y,0,1,false,3);else d.line(160,y,340,y,0,1,false,3);});
 for(const la of [0,30,60,90])d.note(92,Y(la),`${la}°`,0);
 [[0,'Low: ITCZ, rain',1],[30,'High: dry, deserts',3],[60,'Low: storms',1],[90,'High: cold, dry',3]].forEach(([la,t,c])=>d.note(490,Y(la),t,c));
 d.note(490,Y(0)+22,'Blows from the east in the tropics',0);});
const seasonFig=()=>scene('The Sun\'s overhead latitude through the year (tilt 23.5°)',d=>{
 const X=day=>70+day*1.3699,Y=la=>150-la*3.2,S=day=>23.5*Math.sin(2*Math.PI*(day-80)/365.25);
 d.line(70,Y(0),570,Y(0),0,0,false,2);d.line(70,Y(23.5),570,Y(23.5),4,0,true,1);d.line(70,Y(-23.5),570,Y(-23.5),4,0,true,1);
 for(let k=0;k<24;k++){const a=Math.round(k*365/24),b=Math.round((k+1)*365/24);d.line(X(a),Y(S(a)),X(b),Y(S(b)),3,0,false,3);}
 for(const [day,la,t,col] of [[79,0,'Mar: 0°',1],[172,23.5,'Jun: 23.5° N',3],[265,0,'Sep: 0°',1],[355,-23.5,'Dec: 23.5° S',3]]){d.circle(X(day),Y(la),5,col);d.note(X(day),la===0?Y(0)+(day<200?18:-18):Y(la)+(la>0?-14:14),t,col);}
 d.note(62,Y(23.5),'23.5°N',4);d.note(62,Y(-23.5),'23.5°S',4);d.note(62,Y(0),'0°',0);d.note(320,250,'Jan  to  Dec',0);});
const angleFig=()=>scene('Noon sun angle at 40° N: the same beam, spread over more ground',d=>{
 const draw=(ax,deg,col,t1,t2)=>{const th=deg*Math.PI/180,f=30/Math.sin(th),L=110;
  d.line(ax-50,190,ax+f+60,190,0,0,false,2);d.line(ax,190,ax+f,190,col,0,false,5);
  for(const bx of [ax,ax+f])d.line(bx+L*Math.cos(th),190-L*Math.sin(th),bx,190,3,1,false,2);
  d.note(ax+f/2,210,t1,col);d.note(ax+f/2,228,t2,col);};
 draw(110,73.5,2,'June: 73.5° high','ground spread x1.04');draw(380,26.5,1,'December: 26.5° high','ground spread x2.24');
 d.note(320,66,'Sun angle = 90 - |latitude - subsolar latitude|',4);});
const koppenFig=()=>scene('Five broad Koppen groups (simplified)',d=>{
 const cells=[['A  Tropical','coldest month','18 °C or more',3],['B  Dry','evaporation','beats rain',0],['C  Temperate','coldest month','-3 to 18 °C',2],['D  Continental','coldest month','under -3 °C',1],['E  Polar','warmest month','under 10 °C',4]];
 cells.forEach(([a,b,c,col],k)=>{const x=50+k*110;d.box(x,96,100,90,col);d.note(x+50,118,a,col);d.note(x+50,146,b,0);d.note(x+50,166,c,0);});
 d.note(320,70,'Check E first, then A, then cold winters (D); the rest are C',4);d.note(320,222,'Versions differ: some use 0 °C, not -3 °C. Each group has subtypes.',0);});
